# Логику не трогает: рубильник читается из os.environ живого процесса, а поднять процесс с
# новым .env можно только рестартом. ВЫКЛЮЧЕНИЕ — НЕ правкой .env (унаследованную «1» ноль из
# файла не перезапишет, override=False), а стоп-файлом pc_orchestrator.step_selfheal.off.
