# ─── «СВЯЗИ НЕТ» — ИЗМЕРЯЕМОЕ СОСТОЯНИЕ, А НЕ ДОГАДКА (класс 05.08.2026) ─────────────────────
# ПОСЫЛКА (замер, docs/artifacts/2026-08-05-three-states-one-root.md): пробы достижимости в репо
# не было вовсе, а слово «сеть» в логе демона за 14 суток — 0 раз при 89 голых именах исключений.
# Поэтому обрыв 04.08 (75 м 16 с) система назвала тремя НЕВЕРНЫМИ именами сразу: «ошибка
# исполнения» задаче, «пробуждение ПК» витку (18 раз), «умер 3 раза подряд» клиентскому боту.
#
# ЧЕМ МЕРИМ — БЕСПЛАТНО, БЕЗ ЕДИНОГО НОВОГО ЗАПРОСА. Свидетели — вызовы, которые контур и так
# делает каждый цикл: мост (`get_pending`), GitHub (авто-фетч), API модели (её собственный текст
# в выводе headless). Прямая проба DNS (27,1 мс замерено) НЕ заводится: она не нужна, пока есть
# бесплатные свидетели, и стоит на два порядка дороже всего остального.
#
# ПРАВИЛО ВЕРДИКТА. Подтверждение связи ОДНИМ каналом гасит отказы ВСЕХ (мы доказанно в сети —
# значит лежит конкретный сервис, а не связь). «Связи нет» объявляем только когда молчат ДВА
# независимых канала: один молчащий канал — это «связь не подтверждена», и врать про сеть по
# нему нельзя. Ровно так 04.08 совпали мост + GitHub + API, и ровно так 354 отказа
# `BridgeTransportError` при живой сети не дают ни одного ложного обрыва (их класс — «мост
# ответил», см. bridge_http.error_kind).
LINK_OK = "связь есть"
LINK_LOST = "связи нет"
LINK_UNSURE = "связь не подтверждена"
LINK_CH_BRIDGE = "мост"
LINK_CH_GIT = "github"
LINK_CH_API = "api модели"
LINK_MIN_FAILS = 2       # столько сетевых отказов подряд, чтобы одиночный канал вообще высказался
LINK_STALE_SEC = int(os.getenv("PC_LINK_STALE_SEC", "3600") or "3600")   # старше — не свидетельство
LINK_OUTAGE_KEEP = 50    # кап истории окон обрыва (нужны только свежие, для возраста задач)
LINK_JOURNAL_SEC = 300   # окно короче — только лог: журнал это индекс, а не поток мелочей


class LinkWatch:
    """Свидетели внешней связи и вердикт по ним. Чистая машина состояний: ни сети, ни ввода-вывода,
    ни логов — событие возвращается вызывающему, а говорит с владельцем он (`net_witness`).

    `ok` у свидетельства ТРОИЧЕН, и это главное в контракте:
        True  — связь ПОДТВЕРЖДЕНА (ответ получен: хоть ok, хоть HTTP 500, хоть потерянная расписка);
        False — до адресата НЕ ДОШЛИ (сетевой класс отказа);
        None  — свидетельства нет (отказ не опознан). «Не измерил» не смеет выдавать себя ни за
                «связь есть», ни за «связи нет» — это тот же разворот, что `pids is None` у
                вотчдога (#171) и `_in_status` у моста.
    ПАМЯТЬ — ТОЛЬКО В ПРОЦЕССЕ: рестарт демона окна обрыва теряет, и поведение откатывается к
    прежнему (возраст задачи не уменьшается, вердикт «связь есть»). Осознанный fail-open: state-файл
    ради этого заводить дороже, чем стоит сама поправка."""

    def __init__(self):
        self.reset()

    def reset(self):
        self.fails = {}          # канал → {"since": ts, "last": ts, "n": int, "text": str}
        self.ok_at = {}          # канал → ts последнего подтверждения связи
        self.down_since = None   # начало ОТКРЫТОГО окна «связи нет» | None
        self.outages = []        # закрытые окна [(начало, конец)] — по ним считается возраст задач

    def witness(self, channel, ok, detail="", now=None):
        """Свидетельство канала. → событие для владельца: 'lost' | 'back' | None."""
        now = time.time() if now is None else now
        if ok is None:
            return self._settle(now)                 # не опознали — состояние не трогаем вовсе
        if ok:
            self.ok_at[channel] = now
            self.fails.clear()                       # связь доказана — молчание прочих объяснено сервисом
        else:
            for ch, rec in list(self.fails.items()):  # протухшее свидетельство не копим
                if now - rec["last"] > LINK_STALE_SEC:
                    self.fails.pop(ch, None)
            rec = self.fails.get(channel) or {"since": now, "n": 0, "text": ""}
            rec["n"] += 1
            rec["last"] = now
            rec["text"] = str(detail or "")[:300]
            self.fails[channel] = rec
        return self._settle(now)

    def verdict(self, now=None):
        """→ (имя, [каналы], since|None). Имя — ИЗМЕРЕННОЕ состояние, а не предположение."""
        now = time.time() if now is None else now
        fresh = {c: r for c, r in self.fails.items() if now - r["last"] <= LINK_STALE_SEC}
        if len(fresh) >= 2:
            return (LINK_LOST, sorted(fresh), min(r["since"] for r in fresh.values()))
        if len(fresh) == 1:
            ch, rec = next(iter(fresh.items()))
            if rec["n"] >= LINK_MIN_FAILS:
                return (LINK_UNSURE, [ch], rec["since"])
        return (LINK_OK, [], None)

    def lost(self, now=None):
        return self.verdict(now)[0] == LINK_LOST

    def _settle(self, now):
        lost = self.lost(now)
        if lost and self.down_since is None:
            self.down_since = self.verdict(now)[2] or now
            return "lost"
        if not lost and self.down_since is not None:
            self.outages = (self.outages + [(self.down_since, now)])[-LINK_OUTAGE_KEEP:]
            self.down_since = None
            return "back"
        return None

    def outage_seconds(self, since_ts, until_ts, now=None):
        """Сколько секунд окна [since_ts, until_ts] пришлось на ПОДТВЕРЖДЁННОЕ «связи нет».
        Отсюда берётся возраст задачи, не растущий, пока полоса непроверяема, — та же дисциплина,
        что «бюджет тратится только на бодрствование» (`_wait_awake`)."""
        now = time.time() if now is None else now
        wins = list(self.outages) + ([(self.down_since, now)] if self.down_since is not None else [])
        return sum(max(0.0, min(until_ts, b) - max(since_ts, a)) for a, b in wins)


_link = LinkWatch()


def link_ok_by_kind(kind):
    """Класс отказа (`bridge_http.KIND_*`) → троичное свидетельство о СВЯЗИ.
    Ответ моста любым кодом/телом доказывает связь; «не опознали» не доказывает НИЧЕГО."""
    if kind == bridge_http.KIND_NETWORK:
        return False
    if kind in (bridge_http.KIND_HTTP, bridge_http.KIND_BRIDGE):
        return True
    return None


def net_witness(channel, ok, detail="", now=None, watch=None, journal=None, logger=None):
    """Свидетельство канала + ОДНА строка владельцу на смене состояния (не на каждом отказе).
    → событие ('lost'|'back'|None). Всё внешнее инъектируется — голдены гоняются без сети."""
    w = _link if watch is None else watch
    lg = log if logger is None else logger
    ev = w.witness(channel, ok, detail=detail, now=now)
    if ev == "lost":
        _, chans, since = w.verdict(now)
        lg.error("СВЯЗИ НЕТ: молчат каналы %s (последнее: %s). Пока связь не подтверждена, ни одна "
                 "задача не объявляется зависшей и ни один провал — виной исполнителя",
                 ", ".join(chans), str(detail or "")[:200])
    elif ev == "back":
        a, b = w.outages[-1]
        dur = int(b - a)
        lg.warning("СВЯЗЬ ВЕРНУЛАСЬ: связи не было %s (%sс) — окно закрыто, полоса снова проверяема",
                   fmt_sleep(dur), dur)
        if dur >= LINK_JOURNAL_SEC:
            # ЖУРНАЛ (§2.3 разбора): разрыв в мозге сегодня неотличим от «ничего не происходило» —
            # за 02–05.08 таких разрывов 24, и авария среди них ничем не выделялась. Одна строка
            # на возврат связи делает молчание НАЗВАННЫМ. Порог 300 с — чтобы мелкие блипы
            # не превращали индекс в поток.
            (journal or _cowork)("связи не было %s (окно закрыто) — задачи и процессы в этом окне "
                                 "не судились: непроверяемое не объявляется мёртвым" % fmt_sleep(dur))
    return ev


def link_note(prefix=""):
    """Состояние связи ОДНОЙ строкой для диагноза («связи нет 12 м 30 с, каналы: мост, github»).
    Пустая строка, когда связь подтверждена: молчать о норме дешевле, чем шуметь."""
    name, chans, since = _link.verdict()
    if name == LINK_OK:
        return ""
    age = fmt_sleep(time.time() - since) if since else "?"
    return "%s%s %s (каналы: %s)" % (prefix, name, age, ", ".join(chans) or "—")


# ── ПОТОЛОК ВРЕМЕНИ НА МОСТ В ОДНОМ ВИТКЕ (класс 04.09.2026) ──────────────────────────────────
# ДЕФЕКТ. Виток исполняется СИНХРОННО (потоков в демоне нет вовсе), а лестница повторов ОДНОГО
# вызова моста собственного потолка не имеет: `bridge_http` даёт первое плечо + MAX_HOPS=6 хопов
# × ECHO_TRIES=3 попытки расписки, и всё это ЦЕЛИКОМ переспрашивается READ_TRIES=3 раза для GET.
# ЗАМЕР (инъекция opener/sleeper в живой `exchange`, сеть не задета; _scratch_bridge_budget_0904/
# probe_ceiling.py): один GET на БОЕВОМ таймауте держит виток до 4802 с = 80 мин, на 30 с — 1622 с.
# Оценка «9 мин» (30×3×6) неверна дважды: демон берёт `Bridge(timeout=90)`, а не DEFAULT_TIMEOUT=30,
# и внешний цикл READ_TRIES в ней пропущен. Пока лестница лезет, встают ВСЕ потребители витка —
# ящик, ступени, витрина: у ящика одного до 13 обращений за виток (папка 1 + шапка 1 + открытые 4
# + закрытые 2 + тела READ_MAX=5).
#
# ПОТОЛОК СТОИТ ТОЛЬКО НА ПУТИ ЧТЕНИЯ, И ЭТО ГЛАВНОЕ ЗДЕСЬ. Повтор на пути ЗАПИСИ — единственное,
# чем держится надёжность мутации (расписка забирается ПОСЛЕ того, как Apps Script исполнил
# действие), и резать его значило бы разменять зависший виток на потерянную мутацию — дефект
# дороже исходного. Поэтому из-под потолка выведены ДВЕ вещи, а не одна:
#   • все POST (`_post`) — мутации;
#   • `_in_status` — формально GET, но это ДОКАЗАТЕЛЬСТВО пути записи (CLAIM-VERIFY/COMPLETE-VERIFY,
#     :737/:758). Срезав его, мы превратили бы долетевший claim в сироту — ровно тот же размен.
# Чтение же дешевле повторить следующим витком: оно идемпотентно и ничего не теряет.
#
# ПОРОГ 900 с ИЗМЕРЕН, А НЕ НАЗНАЧЕН. Корпус — 200 строк «залипание вызова моста» живого
# `pc_orchestrator.log` (у них сон измерен и равен 0, связь есть, работа в отрезке не шла):
# медиана 349 · p90 504 · p95 605 · p99 779 · MAX 1437 с. Порог 900 с — это 1.16× p99, и на всём
# корпусе он тронул бы РОВНО ОДИН виток из 200 — тот самый патологический 1437 с. Ниже брать
# нельзя: 600 с срезали бы 11 витков, 480 с — 30, то есть прибор начал бы резать здоровое.
# Сверху порог заперт сторожем: `WD_PRODUCT_SILENT` = 1800 с, и виток обязан замкнуться ДО того,
# как сторож назовёт демона вставшим. 900 с оставляют ему ровно вдвое.
# СТОРОЖА НЕ ТРОГАЕМ НИ СТРОКОЙ: он судит тишину и судит верно. Потолок как раз и делает его
# рассуждение честным — комментарий у `WD_PRODUCT_SILENT` считает потолок одного вызова равным
# ≈28 мин (по timeout=30), тогда как на боевых 90 с он 80 мин, то есть ВЫШЕ порога сторожа;
# с потолком витка этот перекос закрыт со стороны витка, а не подкруткой сторожа.
# ОТКАТ: `PC_BRIDGE_LOOP_BUDGET=0` — ветка мертва целиком, поведение прежнее.
BRIDGE_LOOP_BUDGET = float(os.getenv("PC_BRIDGE_LOOP_BUDGET", "900") or "900")
KIND_BUDGET = "budget"                 # третий исход: НЕ СПРАШИВАЛИ. Не ноль и не отказ прибора
BUDGET_ERROR = "BridgeBudgetExhausted"  # имя в поле `error` — контракт «type(e).__name__» сохранён
BUDGET_TEXT = ("не спрашивали: мост был занят — потолок времени на мост в этом витке (%.0fс) "
               "исчерпан, остаток обращений отложен до следующего витка")


class BridgeLoopBudget:
    """Сколько секунд витка уже съел мост. Чистый счётчик, голден; часы инъектируются.

    ТРЕТИЙ ИСХОД, а не ноль: исчерпание потолка НЕ отказ прибора и НЕ пустой ответ. Потребитель
    обязан отличить «спросили, и там пусто» от «не спрашивали, потому что мост был занят», иначе
    ящик возьмёт решение на несуществующих данных."""

    def __init__(self, limit=None, clock=None):
        self.clock = clock or time.perf_counter
        self.reset(limit)

    def reset(self, limit=None):
        self.limit = BRIDGE_LOOP_BUDGET if limit is None else float(limit)
        self.spent = 0.0
        self.calls = 0
        self.tripped_on = ""      # действие, НА КОТОРОМ потолок был перейдён
        self.skipped = []         # действия, которых не сделали вовсе
        self.said = False         # событие уже сказано в лог (см. `_bridge_budget_note`)

    @property
    def on(self):
        return self.limit > 0

    def spend(self, sec, action=""):
        self.spent += max(0.0, float(sec))
        self.calls += 1
        if self.on and not self.tripped_on and self.spent >= self.limit:
            self.tripped_on = str(action or "?")

    def exhausted(self):
        return self.on and self.spent >= self.limit

    def skip(self, action):
        """Обращение, которого не делаем. Имена не копим бесконечно — это индекс, а не архив."""
        a = str(action or "?")
        if a not in self.skipped:
            self.skipped.append(a)
        return {"ok": False, "error": BUDGET_ERROR, "error_kind": KIND_BUDGET,
                "error_text": BUDGET_TEXT % self.limit, "budget_skipped": True, "ms": 0}

    def report(self):
        """Событие СО СЛОВАМИ или пустая строка. Молчаливое сокращение витка запрещено —
        оно неотличимо от поломки."""
        if not self.skipped and not self.tripped_on:
            return ""
        return ("ПОТОЛОК МОСТА: виток отдал мосту %.0fс из %.0fс за %d вызов(ов) — потолок перейдён "
                "на «%s», НЕ СПРАШИВАЛИ вовсе: %s. Это не ноль и не отказ прибора: отложено до "
                "следующего витка, виток закрываю штатно"
                % (self.spent, self.limit, self.calls, self.tripped_on or "?",
                   ", ".join(self.skipped) or "—"))


_bridge_budget = BridgeLoopBudget()


def _bridge_budget_note(budget=None, logger=None):
    """Событие исчерпания в лог демона РОВНО ОДИН РАЗ за виток. → сказанная строка ("" — молчали).

    Идемпотентность здесь не украшение: строка зовётся и из нормального конца витка, и из ветки
    `except` (виток, упавший после обрезки, обязан всё равно назвать обрезку), а два одинаковых
    предложения о ПОТОЛКЕ в логе читались бы как два разных сокращённых витка."""
    b = _bridge_budget if budget is None else budget
    if b.said:                    # прямым полем, а не getattr с умолчанием: `reset()` ставит его
        return ""                 # всегда, и «нет атрибута» здесь было бы не умолчанием, а ошибкой
    line = b.report()
    if not line:
        return ""
    b.said = True
    (logger or log).warning("%s", line)
    return line


# ------------------------------- Bridge (очередь) ----------------------------

class Bridge:
    """Минимальный клиент очереди Bridge (совместим с протоколом VPS). read=GET, мутации=POST.

    ТРАНСПОРТ — `bridge_http`, а не голый urlopen (класс 02.08.2026, разбор
    docs/artifacts/2026-08-02-bridge-receipt-leg-not-token.md): мост отвечает 302 на второе
    плечо, а `urlopen` идёт по нему сам и переигрывает POST как GET без тела — расписку на
    claim/complete выдавал `doGet` («Invalid or missing token») при УЖЕ ЛЁГШЕЙ мутации.
    `opener` — точка инъекции тестов, боевой путь его не задаёт."""

    # Отказы, которые мост дал ПО СУЩЕСТВУ: запрос дошёл до doPost и разобран, мутации не было.
    # Перечитывать статус после них незачем (и вредно: лишний запрос в мост на ровном месте).
    _CLAIM_SEMANTIC = ("not_found", "wrong_lane", "no_id")
    _COMPLETE_SEMANTIC = ("not_found", "no_id", "bad_status")

    def __init__(self, url=None, token=None, timeout=90, opener=None, witness=None):
        self.url = url or BRIDGE_URL
        self.token = token or BRIDGE_TOKEN
        self.timeout = timeout
        self.opener = opener
        self.witness = witness          # точка инъекции свидетеля связи (боевой путь его не задаёт)

    def _call(self, method, params=None, payload=None, budget=None, action="", cuttable=True):
        """Один обмен с мостом + ДВА бесплатных числа вокруг уже делаемого вызова: класс отказа
        и потраченные миллисекунды (латентность моста не мерилась вообще — «ответил за 2,3 с» и
        «залип на 122,6 с» были для системы одним событием).

        КОНТРАКТ ОТВЕТА СОХРАНЁН ДОСЛОВНО: `error` — по-прежнему `type(e).__name__`, на него
        смотрят семантические наборы (`_CLAIM_SEMANTIC`) и голдены. Поля ДОБАВЛЕНЫ, а не заменены:
        `error_kind` (сеть/http/мост/иное), `error_text` (разбор по существу), `ms`.

        ДВА РАЗНЫХ ВОПРОСА, И ИХ НЕЛЬЗЯ СЛИВАТЬ В ОДИН ФЛАГ:
          `cuttable` — можно ли ЭТОТ вызов не делать вовсе (только путь ЧТЕНИЯ);
          учёт времени — идёт ВСЕГДА, у любого вызова, включая мутации.
        Слей их — и медленная запись стала бы для витка БЕСПЛАТНОЙ: замер даёт одному POST до
        1721 с на боевом таймауте, и виток, потративший их, продолжал бы спокойно читать дальше,
        а потолок обходился бы сам собой. Поэтому мутация не режется, но своё время в счётчик
        отдаёт — и следующее ЧТЕНИЕ уже упрётся в потолок.
        `budget` — точка инъекции (None = боевой `_bridge_budget`)."""
        b = _bridge_budget if budget is None else budget
        name = str(action or method)
        if b is not None and cuttable and b.exhausted():
            return b.skip(name)                      # третий исход: сети не касаемся вовсе
        t0 = time.perf_counter()
        wit = self.witness or net_witness
        try:
            data = bridge_http.request_json(self.url, method, params=params, payload=payload,
                                            timeout=self.timeout, opener=self.opener)
        except Exception as e:
            kind = bridge_http.error_kind(e)
            text = bridge_http.explain(e, self.timeout)
            wit(LINK_CH_BRIDGE, link_ok_by_kind(kind), detail=text)
            return {"ok": False, "error": type(e).__name__, "error_kind": kind,
                    "error_text": text, "ms": int((time.perf_counter() - t0) * 1000)}
        finally:
            if b is not None:
                b.spend(time.perf_counter() - t0, name)   # платят ВСЕ, включая мутации
        # Мост ОТВЕТИЛ — связь доказана даже если ответ отрицательный по существу (`ok:false`).
        wit(LINK_CH_BRIDGE, True)
        return data

    def _get(self, action, budget=None, cuttable=True, **params):
        q = {"action": action, "token": self.token, **{k: v for k, v in params.items() if v is not None}}
        return self._call("GET", params=q, budget=budget, action=action, cuttable=cuttable)

    def _post(self, action, **fields):
        # МУТАЦИЯ НЕ РЕЖЕТСЯ НИ ОДНОЙ ВЕТКОЙ (`cuttable=False`): резать запись значило бы разменять
        # зависший виток на потерянную мутацию — дефект дороже исходного. Время своё она платит.
        return self._call("POST", payload={"action": action, "token": self.token, **fields},
                          action=action, cuttable=False)

    def get_pending(self, status, lane=LANE):
        return self._get("get_pending", status=status, lane=lane)

    # ── СУДИТЬ ПО ФАКТУ, А НЕ ПО РАСПИСКЕ ────────────────────────────────────────────────
    # Расписка моста описывает ДОСТАВКУ ОТВЕТА, а не судьбу мутации: второе плечо (echo) падает
    # уже ПОСЛЕ того, как Apps Script исполнил действие. Живой случай — задача 193 (02.08):
    # `claim_task` вернул `unauthorized`, демон написал «claim не удался — пропуск», а задача
    # ЛЕГЛА в `in_progress` и провисела до реапера. Поэтому отказ расписки больше не вердикт:
    # вердикт выносит перечитанный СТАТУС — ровно как обратное чтение дока у писателя журнала.
    # Форма списана с VPS `_claim_task_verified` (08.07.2026, тот же класс на своей полосе);
    # мутацию НЕ переотправляем никогда (claim не идемпотентен, а повторный complete затёр бы
    # result), только перечитываем факт.

    def _in_status(self, tid, status):
        """Задача tid СЕЙЧАС в статусе status на МОЕЙ полосе? True | False | None (не прочитали).
        None и False разведены: «не знаю» не смеет выдавать себя за «не легло».

        ПОД ПОТОЛОК ВИТКА НЕ ХОДИТ (`budget=False`), хотя формально это GET. Предмет здесь — не
        разведка, а СУДЬБА УЖЕ СДЕЛАННОЙ МУТАЦИИ: этим чтением claim/complete отличают потерянную
        расписку от несостоявшейся записи. Срезанное потолком, оно вернуло бы None → «не знаю» →
        пропуск цикла, и долетевший claim стал бы сиротой. Это ровно тот размен зависшего витка на
        потерянную мутацию, который делать запрещено, — потому путь записи выведен ЦЕЛИКОМ, вместе
        со своим доказательством, а не только POST'ами. Время своё оно, как и мутация, платит."""
        r = self._get("get_pending", status=status, lane=LANE, cuttable=False)
        if not (isinstance(r, dict) and r.get("ok")):
            return None
        return any(str(it.get("id")) == str(tid)
                   for it in (r.get("items") or []) if isinstance(it, dict))

    def claim_task(self, tid):
        r = self._post("claim_task", id=tid)
        if r.get("ok"):
            return r
        err = str(r.get("error") or "")
        if err in self._CLAIM_SEMANTIC:
            return r
        # Одно-воркерность полосы = доказательство владения: pc-задачи клеймит ТОЛЬКО этот демон,
        # а кандидат секунды назад был `new` в этом же цикле. Значит `in_progress` сейчас — наш
        # долетевший claim. Не прочитали / статус иной → прежний пропуск цикла (fail-safe).
        if self._in_status(tid, "in_progress") is True:
            log.warning("CLAIM-VERIFY id=%s: расписка claim — отказ (%s), а задача in_progress на "
                        "моей полосе → claim ДОЛЕТЕЛ, работаю штатно (сироты нет)", tid, err)
            return {"ok": True, "verified_by_fact": True, "receipt_error": err,
                    "task": r.get("task")}
        return r

    def complete_task(self, tid, status, result):
        # ПОСЛЕДНИЙ РУБЕЖ обрезки: сюда стекаются ВСЕ пути (done/failed/цепи/уроки/ревизор), и
        # раньше здесь стоял голый срез — вторая немая точка того же класса. Теперь режет `_cap_result`:
        # тело на диск, в очередь — голова с числами и адресом. Обычный путь этой ветки не задевает:
        # выход `_run_task_impl` уже ужал текст до потолка, и второго тела не появляется.
        r = self._post("complete_task", id=tid, status=status, result=_cap_result(result, tid))
        if r.get("ok"):
            return r
        err = str(r.get("error") or "")
        if err in self._COMPLETE_SEMANTIC:
            return r
        # Спрашиваем ИМЕННО ЗАПРОШЕННЫЙ статус (положительный факт), а не «её больше нет в
        # in_progress»: complete зовут и для approved/needs_approval — там её в in_progress и
        # не было, и отрицательная проверка объявила бы успехом любой отказ.
        if self._in_status(tid, status) is True:
            log.warning("COMPLETE-VERIFY id=%s: расписка complete — отказ (%s), а задача уже в "
                        "статусе %s → запись ДОЛЕТЕЛА, отказ был потерей расписки", tid, err, status)
            return {"ok": True, "verified_by_fact": True, "receipt_error": err}
        return r

    def set_needs_approval(self, tid, what, topic=NEEDS_APPROVAL_TOPIC):
        # topic → Splinter постит красную карточку в эту тему (по уточнению Филиппа — 829).
        return self._post("set_needs_approval", id=tid, what=(what or "")[:RESULT_MAX], topic=topic)

    def approve_task(self, tid, approved_by, origin=ORIGIN_HUMAN, ticket=None):
        """Владелец сказал «да N»: needs_approval→approved + approved_by → {ok}.

        КОНТРАКТ ОДИН В ОДИН С VPS и ничего сверх него: `bridge_client.approve_task` шлёт
        POST `approve_task` с полями `id` и `approved_by` (`devbot._cb_approve` / «да N» зовут
        его как `approve_task(qid, "Filipp")`). Имена полей не выведены по догадке — списаны
        с полосы, которая этим действием живёт каждый день.

        Единственная добавка — `origin` (блок выше): у VPS-клиента он едет автоматически с
        КАЖДЫМ POST, здесь его надо поставить явно, потому что ПК-клиент такого слоя не имеет.
        Билет прикладывается ТОЛЬКО к машинному ответу — ровно как в токен-замке 4.2."""
        f = {"id": tid, "approved_by": approved_by, "origin": (origin or ORIGIN_HUMAN)}
        if f["origin"] == ORIGIN_AGENT and ticket:
            f["ticket"] = ticket
        return self._post("approve_task", **f)

    def task_heartbeat(self, tid):
        return self._post("task_heartbeat", id=tid)

    def enqueue_task(self, frm, text, lane=LANE):
        return self._post("enqueue_task", **{"from": frm, "task_text": text, "lane": lane})


bc = Bridge()


# ------------------------------- утилиты -------------------------------------

def _cowork(line):
    """Строка-итог в cowork_log через скрипт (fire-and-forget).

    КОНТРАКТ СТРОКИ ЖУРНАЛА (28.07.2026): «<ТИП> <ГГГГ-ММ-ДД ЧЧ:ММ UTC>: <текст>», ОДНА запись =
    ОДНА строка. ТИП ставим здесь (наши строки всегда NOTE — знает только источник), ДАТУ ставит
    единственная точка штампа cowork_log_append.stamp_line. Переносы схлопываем В ИСТОЧНИКЕ:
    result задачи бывает многострочным (_clip режет длину, но НЕ переносы), а многострочная
    запись рвёт разбор журнала по заголовкам — и может подсунуть сплиттеру ложный заголовок."""
    try:
        one = " ".join(str(line or "").split())
        subprocess.Popen([VENV_PY, os.path.join(REPO, "cowork_log_append.py"), "NOTE Orchestrator: " + one],
                         cwd=REPO, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL,
                         creationflags=NO_WINDOW)
    except Exception as e:
        log.warning("cowork_log не записан: %s", e)


def _queue_snapshot(why):
    """Слепок состояния очереди в мозг — ОТДЕЛЬНЫМ процессом, fire-and-forget (класс-фикс 539).

    ЗАЧЕМ ВООБЩЕ: Штаб читает мозг САМ, а состояния очереди там не было — между «взял» и «сдал»
    пустота, из которой на полосе VPS родились четыре дубля за трое суток. Там слепок уже стои́т,
    здесь его не было; правило «класс-фикс кладётся на обе полосы».

    ПОЧЕМУ ОТСЮДА, А НЕ ИЗ НАБЛЮДАТЕЛЯ, КАК НА VPS: у соседа слепок снимает слой ожиданий вне
    демона, на ПК он трогать запрещён, а своя задача Планировщика — красная операция. Взамен
    демон кладёт «в работе» САМ, в момент claim — ДО того как встанет на синхронный заход.

    ПОЧЕМУ ОТДЕЛЬНЫМ ПРОЦЕССОМ, а не веткой в обороте: чтение моста и запись в мозг — это секунды
    сети, и внутри `poll_once` они удлиняли бы оборот, чей возраст меряют О2/О4. Спавн копирует
    `_cowork`: без окна, потоки в DEVNULL, ошибка спавна — предупреждение, а не падение оборота.
    Писать или промолчать решает САМ скрипт (пишет только по СМЕНЕ состояния); частота вызова
    отсюда на число записей не влияет."""
    try:
        subprocess.Popen([VENV_PY, os.path.join(REPO, "queue_snapshot_pc.py"), "--tick"],
                         cwd=REPO, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         stdin=subprocess.DEVNULL, creationflags=NO_WINDOW)
    except Exception as e:
        log.warning("слепок очереди (%s) не снят: %s", why, e)


def _srv_delivery():
    """Доставка работы СЕРВЕРНОЙ полосы в общий репозиторий — отдельным процессом, fire-and-forget.

    ЗАЧЕМ ВООБЩЕ: push с сервера отбит аутентификацией, и с 30.08.2026 его коммиты никуда не
    доезжали — замер 03.09: общий main стоя́л на `e646f1f` (30.08), живой main сервера ушёл на
    `f1375cb`, а между ними лежал артефакт серверной разведки, которого на ПК не было ровно
    поэтому. Права записи серверу не выдаём; вместо этого ПК, у которого право уже есть, САМ
    ходит на сервер ЧИТАТЬ и сам кладёт прочитанное в общий репозиторий.

    ПОЧЕМУ ОТСЮДА, А НЕ ИЗ ПЛАНИРОВЩИКА: своя задача Планировщика — красная операция (`schtasks`),
    без владельца её не завести. Демон тикает сам, работает под тем же пользователем (значит видит
    ключ `~/.ssh/turbobaby_vps` и кэш учётных данных git) и уже носит ровно такой вызов для слепка
    очереди. Цена названа вслух в шапке `srv_delivery.py`: вставший демон замораживает доставку.

    ПОЧЕМУ ОТДЕЛЬНЫМ ПРОЦЕССОМ: два похода в сеть — это секунды, и внутри `poll_once` они удлиняли
    бы оборот, чей возраст меряют О2/О4. ЧАСТОТУ решает САМ скрипт по своему штампу (30 мин по
    умолчанию), а не частота вызова отсюда — так же, как у `queue_snapshot_pc`."""
    try:
        subprocess.Popen([VENV_PY, os.path.join(REPO, "srv_delivery.py"), "--tick"],
                         cwd=REPO, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         stdin=subprocess.DEVNULL, creationflags=NO_WINDOW)
    except Exception as e:
        log.warning("доставка серверной полосы не запущена: %s", e)


def _notify(text):
    """Пуш Филиппу через dispatch_notify (fire-and-forget, человекочитаемо)."""
    try:
        subprocess.Popen([VENV_PY, DNOTIFY, text], cwd=REPO,
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL,
                         creationflags=NO_WINDOW)
    except Exception as e:
        log.warning("пуш не отправлен: %s", e)


# --- карточки цепи: restart-proof дедуп + мьют финализированных (спам-луп 14:25 14.07) ---
# Живой провал: залп «План цепи #101» (41 карточка исторических версий) в личку при рестарте
# демона 0bd46c0. Корень двойной: (1) гейт-тесты test_pc_local_dec звали НЕзамоканный
# _notify_chain_card — каждый прогон гейта стрелял реальными subprocess-карточками фикстурной
# цепи 101 (LocBase теперь мокает); (2) у самой функции не было ни restart-proof дедупа, ни
# исключения финализированных цепей. Класс: «отправлено» — в state-файле по ключу события
# (родитель + sha1 текста карточки: текст несёт версию плана и номер шага), финализированные
# цепи (сводка поставлена / помечены вручную) не анонсируются НИКОГДА.
CHAIN_CARD_STATE = _state(os.path.join(REPO, "pc_orchestrator.chain_cards.json"))
CHAIN_CARD_SENT_MAX = 500          # кап истории ключей (старые события дедупить незачем)


def _chain_cards_read(path=None):
    """State карточек цепей {'sent': [ключи], 'final': [pid]} → dict ({} при отсутствии/бое)."""
    try:
        with open(path or CHAIN_CARD_STATE, encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _chain_cards_write(d, path=None):
    try:
        with open(path or CHAIN_CARD_STATE, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False)
    except Exception as e:
        log.warning("state карточек цепей не записался (%s) — дедуп деградирует, не критично", e)


def _loc_mark_chain_final(pid, path=None):
    """Пометить цепь pid финализированной: её карточки БОЛЬШЕ НИКОГДА не анонсируются
    (restart-proof). Зовётся при постановке сводки (halt/finish/стоп) и при узнавании
    закрытой цепи после рестарта; вручную — для исторических артефактов (цепь 101)."""
    st = _chain_cards_read(path)
    fin = set(int(x) for x in (st.get("final") or []))
    if int(pid) in fin:
        return
    fin.add(int(pid))
    st["final"] = sorted(fin)
    _chain_cards_write(st, path)


def _notify_chain_card(pid, text, state_path=None, spawn=None):
    """Карточка цепи владельцу с кнопками [⏹ Стоп цепи][📊 Статус цепи] (dispatch_notify --card,
    fire-and-forget). callback слушает pc_agent (owner-gate). Сбой доставки тик демона не роняет.
    Дедуп restart-proof: ключ события (pid+sha1 текста) в CHAIN_CARD_STATE — рестарт демона НЕ
    повторяет уже отправленные; финализированные цепи (final) не анонсируются никогда."""
    st = _chain_cards_read(state_path)
    if int(pid) in set(int(x) for x in (st.get("final") or [])):
        log.info("карточка цепи %s подавлена: цепь финализирована", pid)
        return False
    key = f"{pid}:{hashlib.sha1(str(text).encode('utf-8')).hexdigest()[:12]}"
    sent = list(st.get("sent") or [])
    if key in sent:
        log.info("карточка цепи %s подавлена: событие уже отправлялось (restart-proof дедуп)", pid)
        return False
    try:
        if spawn is not None:
            spawn(pid, text)
        else:
            subprocess.Popen([VENV_PY, DNOTIFY, "--card", str(pid), str(text)], cwd=REPO,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                             stdin=subprocess.DEVNULL, creationflags=NO_WINDOW)
    except Exception as e:
        log.warning("карточка цепи не отправлена (pid=%s): %s", pid, e)
        return False
    st["sent"] = (sent + [key])[-CHAIN_CARD_SENT_MAX:]
    _chain_cards_write(st, state_path)
    return True


def _notify_critical(text):
    """Критический инцидент КОНТУРА (доказанная смерть демона / 3-смерти-halt клиент-бота /
    halt-слепота контур-вотчдога) → тема Инбокс HQ-форума (INBOX_TOPIC_ID=1160); личка Филиппа —
    ФОЛБЭК при недоступности форума. Маршрут «форум → личка» реализует dispatch_notify --critical.
    Fire-and-forget: сбой доставки НЕ роняет тик демона. Гигиена пульта: сюда идут ТОЛЬКО реальные
    инциденты (не рутинные done/failed задач — те видны в темах постановки 328/829, см. _notify_task)."""
    try:
        subprocess.Popen([VENV_PY, DNOTIFY, "--critical", text], cwd=REPO,
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL,
                         creationflags=NO_WINDOW)
    except Exception as e:
        log.warning("критический пуш не отправлен: %s", e)


def _notify_topic(topic, text):
    """Сигнал в КОНКРЕТНУЮ тему форума через `dispatch_notify --topic <id>` — тот же канал, что
    завёл детектор немоты (session_watch, 29.07): тема постановки задач 328, фолбэк инбокс 1160 →
    личка реализован внутри dispatch_notify. Fire-and-forget: сбой доставки НЕ роняет тик демона."""
    try:
        subprocess.Popen([VENV_PY, DNOTIFY, "--topic", str(topic), text], cwd=REPO,
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL,
                         creationflags=NO_WINDOW)
    except Exception as e:
        log.warning("сигнал в тему %s не отправлен: %s", topic, e)


def _notify_task(kind, tid, text):
    """Уведомление о жизненном цикле ЗАДАЧИ (done/failed/needs_approval) — ТОЛЬКО про личку-пуш.
    Итог в cowork_log и карточку темы пишет вызывающий (bc.complete_task/_cowork).

    ЛИЧКА-ПУШ ОТСЮДА СНЯТ ЦЕЛИКОМ (05.08.2026). done/failed сняли раньше: они видны в темах
    постановки (328/задачи, 829/красное). Теперь снят и needs_approval, и довод у него ровно
    тот же, только доказанный: «call-to-action, требующий реакции» — это КАРТОЧКА ГАРДА, а её
    владелец уже получил, и дважды. Порядок доставки одного красного (замер по логам 05.08):

      1. `pretool_guard._emit_ask` → `_push` → `dispatch_notify` → ЛИЧКА: полная карточка
         (что · объект · число · откат · команда). 12:16:23 для задачи 302;
      2. `bc.set_needs_approval(…, topic=NEEDS_APPROVAL_TOPIC)` → devbot → тема 829: та же
         карточка С КНОПКАМИ ✅/❌ — единственная, на которой можно НАЖАТЬ;
      3. эта строка → ЛИЧКА ещё раз: «🔔 задача #302 ждёт твоего «да» — <ПЕРВАЯ СТРОКА той же
         карточки, обрезанная>». 12:23:58 для той же задачи.

    Третье сообщение не добавляло ни факта, ни кнопки: оно беднее первого и слабее второго.
    За 7 суток таких дублей 26.

    Карточка в личке есть ВСЕГДА, и это по построению, а не по везению: `_emit_ask` шлёт её
    пушем, а пропускает пуш ровно тогда, когда латч уже закрыт — то есть когда карточка на
    ПЕРВУЮ красную операцию этого прогона владельцу уже ушла (`_write_marker` → False).

    Снятие НЕ молчаливое (доктрина лога полосы): строка ниже называет и вид, и задачу, и текст,
    который раньше уезжал в личку, — иначе пропажа привычного сообщения читалась бы как сбой
    доставки. Она же держит `_human` живым потребителем."""
    log.info("личка не дублируется (%s id=%s): карточка уже в личке (гард) и в теме %s "
             "с кнопками | %.160s", kind, tid, NEEDS_APPROVAL_TOPIC, _human(kind, tid, text))


