# активность С ПРОШЛОГО ПРОГОНА, и собирает по каждому ПАКЕТ для ревизии (следующие шаги 262 его
# обработают — здесь ТОЛЬКО read-only отбор+сборка, ничего не пишем ни в БД, ни клиенту).
